xpath.script:
(function(){
    try {
        var btn = document.currentScript.previousElementSibling;
        var templateId = btn && btn.dataset.productTemplateId;
        if (!templateId) return;
        var ids = JSON.parse(localStorage.getItem('av_wish_ids') || '[]');
        if (ids.includes(String(templateId))) {
            var icon = btn.querySelector('.fa');
            if (icon) { icon.className = icon.className.replace('fa-star-o', 'fa-star'); }
            btn.title = 'Added to wishlist';
        }
    } catch(e) {}
})();
